def add_constraints(opt):
    for f in friends:
        opt.add(Or(meet[f], pos[f] == -1))
        opt.add(Implies(meet[f], pos[f] >= 0))
        opt.add(Implies(meet[f], pos[f] <= 2))

        opt.add(Implies(meet[f], start[f] >= avail_start[f]))
        opt.add(Implies(meet[f], end[f] <= avail_end[f]))
        opt.add(Implies(meet[f], end[f] == start[f] + min_duration[f]))

        opt.add(start[f] >= 0)
        opt.add(start[f] <= 1440)
        opt.add(end[f] >= 0)
        opt.add(end[f] <= 1440)

    for i in range(len(friends)):
        for j in range(len(friends)):
            if i == j:
                continue

            fi = friends[i]
            fj = friends[j]

            opt.add(Implies(meet[fi] & meet[fj], pos[fi] != pos[fj]))

            opt.add(
                Implies(
                    meet[fi] & meet[fj] & (pos[fj] == pos[fi] + 1),
                    start[fj] >= end[fi] + travel[(locations[fi], locations[fj])]
