        "avail_end": 15 * 60 + 15,
        "min": 30,
    },
}

solver = Optimize()

met = {}
start = {}
end = {}
dur = {}
pos = {}

for name, f in friends.items():
    met[name] = Bool(f"met_{name}")
    start[name] = Int(f"start_{name}")
    end[name] = Int(f"end_{name}")
    dur[name] = Int(f"dur_{name}")
    pos[name] = Int(f"pos_{name}")

    solver.add(pos[name] >= 1, pos[name] <= 2)
    solver.add(dur[name] >= 0, dur[name] <= 1440)
    solver.add(start[name] >= 0, start[name] <= 1440)
    solver.add(end[name] >= 0, end[name] <= 1440)

    solver.add(Implies(
        ~met[name],
        And(start[name] == 0, end[name] == 0, dur[name] == 0, pos[name] == 1)
    ))

    solver.add(Implies(
        met[name],
        And(
            dur[name] >= f["min"],
            start[name] >= f["avail_start"],
            end[name] == start[name] + dur[name],
            end[name] <= f["avail_end"]
        )
    ))

solver.add(Implies(
    And(met["James"], met["Robert"]),
    pos["James"] != pos["Robert"]
))

for name, f in friends.items():
    other = "Robert" if name == "James" else "James"

    solver.add(Implies(
        And(met[name], pos[name] == 1),
        start[name] >= START_TIME + travel[(START_LOC, f["loc"])]
    ))

    solver.add(Implies(
        And(met[name], pos[name] == 2),
        And(
            met[other],
            pos[other] == 1,
            start[name] >= end[other] + travel[(friends[other]["loc"], f["loc"])]
        )
    ))

finish = Int("finish")
solver.add(finish >= 0, finish <= 1440)

for name in friends:
    solver.add(Implies(met[name], finish >= end[name]))

solver.add(Implies(
    And(~met["James"], ~met["Robert"]),
    finish == 0
))

