    model = solver.model()

    met_names = [
        name for name in friends
        if model.eval(met[name], model_completion=True).as_bool()
    ]
    met_names.sort(key=lambda name: model.eval(pos[name], model_completion=True).as_long())

    itinerary = [f"You start at {START_LOC} at {fmt_time(START_TIME)}."]
    prev_loc = START_LOC
    prev_time = START_TIME

    for name in met_names:
        f = friends[name]
        loc = f["loc"]

        if loc != prev_loc:
            t = travel[(prev_loc, loc)]
            arrive = prev_time + t
            itinerary.append(f"You travel to {loc} in {t} minutes and arrive at {fmt_time(arrive)}.")
        else:
            arrive = prev_time

        start_m = model.eval(start[name], model_completion=True).as_long()
        end_m = model.eval(end[name], model_completion=True).as_long()
        dur_m = model.eval(dur[name], model_completion=True).as_long()

        if start_m > arrive:
            itinerary.append(f"You wait until {fmt_time(start_m)}.")

        itinerary.append(
            f"You meet {name} for {dur_m} minutes from {fmt_time(start_m)} to {fmt_time(end_m)}."
        )

        prev_loc = loc
        prev_time = end_m

    print(itinerary)
